import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    static void bitAdd(long[] t, int i, long x) {
        int n = t.length - 1;
        for (; i <= n; i += i & -i) t[i] += x;
    }

    static long bitSum(long[] t, int i) {
        long s = 0;
        for (; i > 0; i -= i & -i) s += t[i];
        return s;
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long limit = Long.parseLong(next());
        long[] a = new long[(int) n];
        for (int i = 0; i < a.length; i++) a[i] = Long.parseLong(next());

        int cnt = (int) n;
        long[] keys = new long[cnt];
        for (int i = 0; i < cnt; i++) keys[i] = (a[i] << 16) | i;
        Arrays.sort(keys);
        int[] rk = new int[cnt];
        int m = 0;
        long last = -1;
        for (int i = 0; i < cnt; i++) {
            long v = keys[i] >> 16;
            if (v != last) {
                m++;
                last = v;
            }
            rk[(int) (keys[i] & 65535)] = m;
        }
        long[] t = new long[m + 1];
        long inv = 0;
        int lo = 0, best = 0;
        for (int hi = 0; hi < cnt; hi++) {
            inv += (hi - lo) - bitSum(t, rk[hi]);
            bitAdd(t, rk[hi], 1);
            while (inv > limit) {
                inv -= bitSum(t, rk[lo] - 1);
                bitAdd(t, rk[lo], -1);
                lo++;
            }
            if (hi - lo + 1 > best) best = hi - lo + 1;
        }
        System.out.println(best);
    }
}
